ng = "love.filesystem.newFile", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new File object. \n\nIt needs to be opened before it can be accessed.\n\nReturns -\n * file (`File`) - The new File object."}}, newFileData = {binding = "love.filesystem.newFileData", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"contents", "name"}, ["fnl/docstring"] = "Creates a new FileData object from a file on disk, or from a string in memory.\n\nReturns -\n * data (`FileData`) - The new FileData."}}, read = {binding = "love.filesystem.read", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"name", "?size"}, ["fnl/docstring"] = "Read the contents of a file.\n\nReturns -\n * contents (`string`) - The file contents.\n * size (`number`) - How many bytes have been read.\n * contents (`nil`) - returns nil as content.\n * error (`string`) - returns an error message."}}, remove = {binding = "love.filesystem.remove", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"name"}, ["fnl/docstring"] = "Removes a file or empty directory.\n\nReturns -\n * success (`boolean`) - True if the file/directory was removed, false otherwise."}}, setCRequirePath = {binding = "love.filesystem.setCRequirePath", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"paths"}, ["fnl/docstring"] = "Sets the filesystem paths that will be searched for c libraries when require is called.\n\nThe paths string returned by this function is a sequence of path templates separated by semicolons. The argument passed to ''require'' will be inserted in place of any question mark ('?') character in each template (after the dot characters in the argument passed to ''require'' are replaced by directory separators.) Additionally, any occurrence of a double question mark ('??') will be replaced by the name passed to require and the default library extension for the platform.\n\nThe paths are relative to the game's source and save directories, as well as any paths mounted with love.filesystem.mount."}}, setIdentity = {binding = "love.filesystem.setIdentity", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"name"}, ["fnl/docstring"] = "Sets the write directory for your game. \n\nNote that you can only set the name of the folder to store your files in, not the location."}}, setRequirePath = {binding = "love.filesystem.setRequirePath", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"paths"}, ["fnl/docstring"] = "Sets the filesystem paths that will be searched when require is called.\n\nThe paths string given to this function is a sequence of path templates separated by semicolons. The argument passed to ''require'' will be inserted in place of any question mark ('?') character in each template (after the dot characters in the argument passed to ''require'' are replaced by directory separators.)\n\nThe paths are relative to the game's source and save directories, as well as any paths mounted with love.filesystem.mount."}}, setSource = {binding = "love.filesystem.setSource", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"path"}, ["fnl/docstring"] = "Sets the source of the game, where the code is present. This function can only be called once, and is normally automatically done by L\195\150VE."}}, setSymlinksEnabled = {binding = "love.filesystem.setSymlinksEnabled", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Sets whether love.filesystem follows symbolic links. It is enabled by default in version 0.10.0 and newer, and disabled by default in 0.9.2."}}, unmount = {binding = "love.filesystem.unmount", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"archive"}, ["fnl/docstring"] = "Unmounts a zip file or folder previously mounted for reading with love.filesystem.mount.\n\nReturns -\n * success (`boolean`) - True if the archive was successfully unmounted, false otherwise."}}, write = {binding = "love.filesystem.write", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"name", "data", "?size"}, ["fnl/docstring"] = "Write data to a file in the save directory. If the file existed already, it will be completely replaced by the new contents.\n\nReturns -\n * success (`boolean`) - If the operation was successful.\n * message (`string`) - Error message if operation was unsuccessful."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to the user's filesystem."}}, focus = {binding = "love.focus", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"focus"}, ["fnl/docstring"] = "Callback function triggered when window receives or loses focus."}}, font = {binding = "love.font", fields = {newBMFontRasterizer = {binding = "love.font.newBMFontRasterizer", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"imageData", "glyphs", "?dpiscale"}, ["fnl/docstring"] = "Creates a new BMFont Rasterizer.\n\nReturns -\n * rasterizer (`Rasterizer`) - The rasterizer."}}, newGlyphData = {binding = "love.font.newGlyphData", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"rasterizer", "glyph"}, ["fnl/docstring"] = "Creates a new GlyphData."}}, newImageRasterizer = {binding = "love.font.newImageRasterizer", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"imageData", "glyphs", "?extraSpacing", "?dpiscale"}, ["fnl/docstring"] = "Creates a new Image Rasterizer.\n\nReturns -\n * rasterizer (`Rasterizer`) - The rasterizer."}}, newRasterizer = {binding = "love.font.newRasterizer", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new Rasterizer.\n\nReturns -\n * rasterizer (`Rasterizer`) - The rasterizer."}}, newTrueTypeRasterizer = {binding = "love.font.newTrueTypeRasterizer", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?size", "?hinting", "?dpiscale"}, ["fnl/docstring"] = "Creates a new TrueType Rasterizer.\n\nReturns -\n * rasterizer (`Rasterizer`) - The rasterizer."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Allows you to work with fonts."}}, gamepadaxis = {binding = "love.gamepadaxis", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "axis", "value"}, ["fnl/docstring"] = "Called when a Joystick's virtual gamepad axis is moved."}}, gamepadpressed = {binding = "love.gamepadpressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "button"}, ["fnl/docstring"] = "Called when a Joystick's virtual gamepad button is pressed."}}, gamepadreleased = {binding = "love.gamepadreleased", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "button"}, ["fnl/docstring"] = "Called when a Joystick's virtual gamepad button is released."}}, getVersion = {binding = "love.getVersion", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current running version of L\195\150VE.\n\nReturns -\n * major (`number`) - The major version of L\195\150VE, i.e. 0 for version 0.9.1.\n * minor (`number`) - The minor version of L\195\150VE, i.e. 9 for version 0.9.1.\n * revision (`number`) - The revision version of L\195\150VE, i.e. 1 for version 0.9.1.\n * codename (`string`) - The codename of the current version, i.e. 'Baby Inspector' for version 0.9.1."}}, graphics = {binding = "love.graphics", fields = {applyTransform = {binding = "love.graphics.applyTransform", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"transform"}, ["fnl/docstring"] = "Applies the given Transform object to the current coordinate transformation.\n\nThis effectively multiplies the existing coordinate transformation's matrix with the Transform object's internal matrix to produce the new coordinate transformation."}}, arc = {binding = "love.graphics.arc", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"drawmode", "x", "y", "radius", "angle1", "angle2", "?segments"}, ["fnl/docstring"] = "Draws a filled or unfilled arc at position (x, y). The arc is drawn from angle1 to angle2 in radians. The segments parameter determines how many segments are used to draw the arc. The more segments, the smoother the edge."}}, captureScreenshot = {binding = "love.graphics.captureScreenshot", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a screenshot once the current frame is done (after love.draw has finished).\n\nSince this function enqueues a screenshot capture rather than executing it immediately, it can be called from an input callback or love.update and it will still capture all of what's drawn to the screen in that frame."}}, circle = {binding = "love.graphics.circle", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode", "x", "y", "radius"}, ["fnl/docstring"] = "Draws a circle."}}, clear = {binding = "love.graphics.clear", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Clears the screen or active Canvas to the specified color.\n\nThis function is called automatically before love.draw in the default love.run function. See the example in love.run for a typical use of this function.\n\nNote that the scissor area bounds the cleared region.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1.\n\nIn versions prior to background color instead."}}, discard = {binding = "love.graphics.discard", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?discardcolor", "?discardstencil"}, ["fnl/docstring"] = "Discards (trashes) the contents of the screen or active Canvas. This is a performance optimization function with niche use cases.\n\nIf the active Canvas has just been changed and the 'replace' BlendMode is about to be used to draw something which covers the entire screen, calling love.graphics.discard rather than calling love.graphics.clear or doing nothing may improve performance on mobile devices.\n\nOn some desktop systems this function may do nothing."}}, draw = {binding = "love.graphics.draw", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"drawable", "?x", "?y", "?r", "?sx", "?sy", "?ox", "?oy", "?kx", "?ky"}, ["fnl/docstring"] = "Draws a Drawable object (an Image, Canvas, SpriteBatch, ParticleSystem, Mesh, Text object, or Video) on the screen with optional rotation, scaling and shearing.\n\nObjects are drawn relative to their local coordinate system. The origin is by default located at the top left corner of Image and Canvas. All scaling, shearing, and rotation arguments transform the object relative to that point. Also, the position of the origin can be specified on the screen coordinate system.\n\nIt's possible to rotate an object about its center by offsetting the origin to the center. Angles must be given in radians for rotation. One can also use a negative scaling factor to flip about its centerline. \n\nNote that the offsets are applied before rotation, scaling, or shearing; scaling and shearing are applied before rotation.\n\nThe right and bottom edges of the object are shifted at an angle defined by the shearing factors.\n\nWhen using the default shader anything drawn with this function will be tinted according to the currently selected color.  Set it to pure white to preserve the object's original colors."}}, drawInstanced = {binding = "love.graphics.drawInstanced", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mesh", "instancecount", "?x", "?y", "?r", "?sx", "?sy", "?ox", "?oy", "?kx", "?ky"}, ["fnl/docstring"] = "Draws many instances of a Mesh with a single draw call, using hardware geometry instancing.\n\nEach instance can have unique properties (positions, colors, etc.) but will not by default unless a custom per-instance vertex attributes or the love_InstanceID GLSL 3 vertex shader variable is used, otherwise they will all render at the same position on top of each other.\n\nInstancing is not supported by some older GPUs that are only capable of using OpenGL ES 2 or OpenGL 2. Use love.graphics.getSupported to check."}}, drawLayer = {binding = "love.graphics.drawLayer", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"texture", "layerindex", "?x", "?y", "?r", "?sx", "?sy", "?ox", "?oy", "?kx", "?ky"}, ["fnl/docstring"] = "Draws a layer of an Array Texture."}}, ellipse = {binding = "love.graphics.ellipse", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode", "x", "y", "radiusx", "radiusy"}, ["fnl/docstring"] = "Draws an ellipse."}}, flushBatch = {binding = "love.graphics.flushBatch", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Immediately renders any pending automatically batched draws.\n\nL\195\150VE will call this function internally as needed when most state is changed, so it is not necessary to manually call it.\n\nThe current batch will be automatically flushed by love.graphics state changes (except for the transform stack and the current color), as well as Shader:send and methods on Textures which change their state. Using a different Image in consecutive love.graphics.draw calls will also flush the current batch.\n\nSpriteBatches, ParticleSystems, Meshes, and Text objects do their own batching and do not affect automatic batching of other draws, aside from flushing the current batch when they're drawn."}}, getBackgroundColor = {binding = "love.graphics.getBackgroundColor", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current background color.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1.\n\nReturns -\n * r (`number`) - The red component (0-1).\n * g (`number`) - The green component (0-1).\n * b (`number`) - The blue component (0-1).\n * a (`number`) - The alpha component (0-1)."}}, getBlendMode = {binding = "love.graphics.getBlendMode", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the blending mode.\n\nReturns -\n * mode (`BlendMode`) - The current blend mode.\n * alphamode (`BlendAlphaMode`) - The current blend alpha mode \226\128\147 it determines how the alpha of drawn objects affects blending."}}, getCanvas = {binding = "love.graphics.getCanvas", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current target Canvas.\n\nReturns -\n * canvas (`Canvas`) - The Canvas set by setCanvas. Returns nil if drawing to the real screen."}}, getCanvasFormats = {binding = "love.graphics.getCanvasFormats", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the available Canvas formats, and whether each is supported.\n\nReturns -\n * formats (`table`) - A table containing CanvasFormats as keys, and a boolean indicating whether the format is supported as values. Not all systems support all formats."}}, getColor = {binding = "love.graphics.getColor", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current color.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1.\n\nReturns -\n * r (`number`) - The red component (0-1).\n * g (`number`) - The green component (0-1).\n * b (`number`) - The blue component (0-1).\n * a (`number`) - The alpha component (0-1)."}}, getColorMask = {binding = "love.graphics.getColorMask", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the active color components used when drawing. Normally all 4 components are active unless love.graphics.setColorMask has been used.\n\nThe color mask determines whether individual components of the colors of drawn objects will affect the color of the screen. They affect love.graphics.clear and Canvas:clear as well.\n\nReturns -\n * r (`boolean`) - Whether the red color component is active when rendering.\n * g (`boolean`) - Whether the green color component is active when rendering.\n * b (`boolean`) - Whether the blue color component is active when rendering.\n * a (`boolean`) - Whether the alpha color component is active when rendering."}}, getDPIScale = {binding = "love.graphics.getDPIScale", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the DPI scale factor of the window.\n\nThe DPI scale factor represents relative pixel density. The pixel density inside the window might be greater (or smaller) than the 'size' of the window. For example on a retina screen in Mac OS X with the highdpi window flag enabled, the window may take up the same physical size as an 800x600 window, but the area inside the window uses 1600x1200 pixels. love.graphics.getDPIScale() would return 2 in that case.\n\nThe love.window.fromPixels and love.window.toPixels functions can also be used to convert between units.\n\nThe highdpi window flag must be enabled to use the full pixel density of a Retina screen on Mac OS X and iOS. The flag currently does nothing on Windows and Linux, and on Android it is effectively always enabled.\n\nReturns -\n * scale (`number`) - The pixel scale factor associated with the window."}}, getDefaultFilter = {binding = "love.graphics.getDefaultFilter", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the default scaling filters used with Images, Canvases, and Fonts.\n\nReturns -\n * min (`FilterMode`) - Filter mode used when scaling the image down.\n * mag (`FilterMode`) - Filter mode used when scaling the image up.\n * anisotropy (`number`) - Maximum amount of Anisotropic Filtering used."}}, getDepthMode = {binding = "love.graphics.getDepthMode", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current depth test mode and whether writing to the depth buffer is enabled.\n\nThis is low-level functionality designed for use with custom vertex shaders and Meshes with custom vertex attributes. No higher level APIs are provided to set the depth of 2D graphics such as shapes, lines, and Images.\n\nReturns -\n * comparemode (`CompareMode`) - Depth comparison mode used for depth testing.\n * write (`boolean`) - Whether to write update / write values to the depth buffer when rendering."}}, getDimensions = {binding = "love.graphics.getDimensions", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the width and height in pixels of the window.\n\nReturns -\n * width (`number`) - The width of the window.\n * height (`number`) - The height of the window."}}, getFont = {binding = "love.graphics.getFont", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current Font object.\n\nReturns -\n * font (`Font`) - The current Font. Automatically creates and sets the default font, if none is set yet."}}, getFrontFaceWinding = {binding = "love.graphics.getFrontFaceWinding", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether triangles with clockwise- or counterclockwise-ordered vertices are considered front-facing.\n\nThis is designed for use in combination with Mesh face culling. Other love.graphics shapes, lines, and sprites are not guaranteed to have a specific winding order to their internal vertices.\n\nReturns -\n * winding (`VertexWinding`) - The winding mode being used. The default winding is counterclockwise ('ccw')."}}, getHeight = {binding = "love.graphics.getHeight", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the height in pixels of the window.\n\nReturns -\n * height (`number`) - The height of the window."}}, getImageFormats = {binding = "love.graphics.getImageFormats", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the raw and compressed pixel formats usable for Images, and whether each is supported.\n\nReturns -\n * formats (`table`) - A table containing PixelFormats as keys, and a boolean indicating whether the format is supported as values. Not all systems support all formats."}}, getLineJoin = {binding = "love.graphics.getLineJoin", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the line join style.\n\nReturns -\n * join (`LineJoin`) - The LineJoin style."}}, getLineStyle = {binding = "love.graphics.getLineStyle", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the line style.\n\nReturns -\n * style (`LineStyle`) - The current line style."}}, getLineWidth = {binding = "love.graphics.getLineWidth", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current line width.\n\nReturns -\n * width (`number`) - The current line width."}}, getMeshCullMode = {binding = "love.graphics.getMeshCullMode", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether back-facing triangles in a Mesh are culled.\n\nMesh face culling is designed for use with low level custom hardware-accelerated 3D rendering via custom vertex attributes on Meshes, custom vertex shaders, and depth testing with a depth buffer.\n\nReturns -\n * mode (`CullMode`) - The Mesh face culling mode in use (whether to render everything, cull back-facing triangles, or cull front-facing triangles)."}}, getPixelDimensions = {binding = "love.graphics.getPixelDimensions", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the width and height in pixels of the window.\n\nlove.graphics.getDimensions gets the dimensions of the window in units scaled by the screen's DPI scale factor, rather than pixels. Use getDimensions for calculations related to drawing to the screen and using the graphics coordinate system (calculating the center of the screen, for example), and getPixelDimensions only when dealing specifically with underlying pixels (pixel-related calculations in a pixel Shader, for example).\n\nReturns -\n * pixelwidth (`number`) - The width of the window in pixels.\n * pixelheight (`number`) - The height of the window in pixels."}}, getPixelHeight = {binding = "love.graphics.getPixelHeight", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the height in pixels of the window.\n\nThe graphics coordinate system and DPI scale factor, rather than raw pixels. Use getHeight for calculations related to drawing to the screen and using the coordinate system (calculating the center of the screen, for example), and getPixelHeight only when dealing specifically with underlying pixels (pixel-related calculations in a pixel Shader, for example).\n\nReturns -\n * pixelheight (`number`) - The height of the window in pixels."}}, getPixelWidth = {binding = "love.graphics.getPixelWidth", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the width in pixels of the window.\n\nThe graphics coordinate system and DPI scale factor, rather than raw pixels. Use getWidth for calculations related to drawing to the screen and using the coordinate system (calculating the center of the screen, for example), and getPixelWidth only when dealing specifically with underlying pixels (pixel-related calculations in a pixel Shader, for example).\n\nReturns -\n * pixelwidth (`number`) - The width of the window in pixels."}}, getPointSize = {binding = "love.graphics.getPointSize", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the point size.\n\nReturns -\n * size (`number`) - The current point size."}}, getRendererInfo = {binding = "love.graphics.getRendererInfo", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets information about the system's video card and drivers.\n\nReturns -\n * name (`string`) - The name of the renderer, e.g. 'OpenGL' or 'OpenGL ES'.\n * version (`string`) - The version of the renderer with some extra driver-dependent version info, e.g. '2.1 INTEL-8.10.44'.\n * vendor (`string`) - The name of the graphics card vendor, e.g. 'Intel Inc'. \n * device (`string`) - The name of the graphics card, e.g. 'Intel HD Graphics 3000 OpenGL Engine'."}}, getScissor = {binding = "love.graphics.getScissor", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current scissor box.\n\nReturns -\n * x (`number`) - The x-component of the top-left point of the box.\n * y (`number`) - The y-component of the top-left point of the box.\n * width (`number`) - The width of the box.\n * height (`number`) - The height of the box."}}, getShader = {binding = "love.graphics.getShader", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current Shader. Returns nil if none is set.\n\nReturns -\n * shader (`Shader`) - The currently active Shader, or nil if none is set."}}, getStackDepth = {binding = "love.graphics.getStackDepth", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current depth of the transform / state stack (the number of pushes without corresponding pops).\n\nReturns -\n * depth (`number`) - The current depth of the transform and state love.graphics stack."}}, getStats = {binding = "love.graphics.getStats", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets performance-related rendering statistics. \n\nReturns -\n * stats (`table`) - A table with the following fields:"}}, getStencilTest = {binding = "love.graphics.getStencilTest", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current stencil test configuration.\n\nWhen stencil testing is enabled, the geometry of everything that is drawn afterward will be clipped / stencilled out based on a comparison between the arguments of this function and the stencil value of each pixel that the geometry touches. The stencil values of pixels are affected via love.graphics.stencil.\n\nEach Canvas has its own per-pixel stencil values.\n\nReturns -\n * comparemode (`CompareMode`) - The type of comparison that is made for each pixel. Will be 'always' if stencil testing is disabled.\n * comparevalue (`number`) - The value used when comparing with the stencil value of each pixel."}}, getSupported = {binding = "love.graphics.getSupported", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the optional graphics features and whether they're supported on the system.\n\nSome older or low-end systems don't always support all graphics features.\n\nReturns -\n * features (`table`) - A table containing GraphicsFeature keys, and boolean values indicating whether each feature is supported."}}, getSystemLimits = {binding = "love.graphics.getSystemLimits", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the system-dependent maximum values for love.graphics features.\n\nReturns -\n * limits (`table`) - A table containing GraphicsLimit keys, and number values."}}, getTextureTypes = {binding = "love.graphics.getTextureTypes", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the available texture types, and whether each is supported.\n\nReturns -\n * texturetypes (`table`) - A table containing TextureTypes as keys, and a boolean indicating whether the type is supported as values. Not all systems support all types."}}, getWidth = {binding = "love.graphics.getWidth", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the width in pixels of the window.\n\nReturns -\n * width (`number`) - The width of the window."}}, intersectScissor = {binding = "love.graphics.intersectScissor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "width", "height"}, ["fnl/docstring"] = "Sets the scissor to the rectangle created by the intersection of the specified rectangle with the existing scissor.  If no scissor is active yet, it behaves like love.graphics.setScissor.\n\nThe scissor limits the drawing area to a specified rectangle. This affects all graphics calls, including love.graphics.clear.\n\nThe dimensions of the scissor is unaffected by graphical transformations (translate, scale, ...)."}}, inverseTransformPoint = {binding = "love.graphics.inverseTransformPoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"screenX", "screenY"}, ["fnl/docstring"] = "Converts the given 2D position from screen-space into global coordinates.\n\nThis effectively applies the reverse of the current graphics transformations to the given position. A similar Transform:inverseTransformPoint method exists for Transform objects.\n\nReturns -\n * globalX (`number`) - The x component of the position in global coordinates.\n * globalY (`number`) - The y component of the position in global coordinates."}}, isActive = {binding = "love.graphics.isActive", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether the graphics module is able to be used. If it is not active, love.graphics function and method calls will not work correctly and may cause the program to crash.\nThe graphics module is inactive if a window is not open, or if the app is in the background on iOS. Typically the app's execution will be automatically paused by the system, in the latter case.\n\nReturns -\n * active (`boolean`) - Whether the graphics module is active and able to be used."}}, isGammaCorrect = {binding = "love.graphics.isGammaCorrect", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether gamma-correct rendering is supported and enabled. It can be enabled by setting t.gammacorrect = true in love.conf.\n\nNot all devices support gamma-correct rendering, in which case it will be automatically disabled and this function will return false. It is supported on desktop systems which have graphics cards that are capable of using OpenGL 3 / DirectX 10, and iOS devices that can use OpenGL ES 3.\n\nReturns -\n * gammacorrect (`boolean`) - True if gamma-correct rendering is supported and was enabled in love.conf, false otherwise."}}, isWireframe = {binding = "love.graphics.isWireframe", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether wireframe mode is used when drawing.\n\nReturns -\n * wireframe (`boolean`) - True if wireframe lines are used when drawing, false if it's not."}}, line = {binding = "love.graphics.line", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x1", "y1", "x2", "y2", "..."}, ["fnl/docstring"] = "Draws lines between points."}}, newArrayImage = {binding = "love.graphics.newArrayImage", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"slices", "?settings"}, ["fnl/docstring"] = "Creates a new array Image.\n\nAn array image / array texture is a single object which contains multiple 'layers' or 'slices' of 2D sub-images. It can be thought of similarly to a texture atlas or sprite sheet, but it doesn't suffer from the same tile / quad bleeding artifacts that texture atlases do \226\128\147 although every sub-image must have the same dimensions.\n\nA specific layer of an array image can be drawn with love.graphics.drawLayer / SpriteBatch:addLayer, or with the Quad variant of love.graphics.draw and Quad:setLayer, or via a custom Shader.\n\nTo use an array image in a Shader, it must be declared as a ArrayImage or sampler2DArray type (instead of Image or sampler2D). The Texel(ArrayImage image, vec3 texturecoord) shader function must be used to get pixel colors from a slice of the array image. The vec3 argument contains the texture coordinate in the first two components, and the 0-based slice index in the third component.\n\nReturns -\n * image (`Image`) - An Array Image object."}}, newCanvas = {binding = "love.graphics.newCanvas", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Creates a new Canvas object for offscreen rendering.\n\nReturns -\n * canvas (`Canvas`) - A new Canvas with dimensions equal to the window's size in pixels."}}, newCubeImage = {binding = "love.graphics.newCubeImage", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename", "?settings"}, ["fnl/docstring"] = "Creates a new cubemap Image.\n\nCubemap images have 6 faces (sides) which represent a cube. They can't be rendered directly, they can only be used in Shader code (and sent to the shader via Shader:send).\n\nTo use a cubemap image in a Shader, it must be declared as a CubeImage or samplerCube type (instead of Image or sampler2D). The Texel(CubeImage image, vec3 direction) shader function must be used to get pixel colors from the cubemap. The vec3 argument is a normalized direction from the center of the cube, rather than explicit texture coordinates.\n\nEach face in a cubemap image must have square dimensions.\n\nFor variants of this function which accept a single image containing multiple cubemap faces, they must be laid out in one of the following forms in the image:\n\n   +y\n\n+z +x -z\n\n   -y\n\n   -x\n\nor:\n\n   +y\n\n-x +z +x -z\n\n   -y\n\nor:\n\n+x\n\n-x\n\n+y\n\n-y\n\n+z\n\n-z\n\nor:\n\n+x -x +y -y +z -z\n\nReturns -\n * image (`Image`) - An cubemap Image object."}}, newFont = {binding = "love.graphics.newFont", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new Font from a TrueType Font or BMFont file. Created fonts are not cached, in that calling this function with the same arguments will always create a new Font object.\n\nAll variants which accept a filename can also accept a Data object instead.\n\nReturns -\n * font (`Font`) - A Font object which can be used to draw text on screen."}}, newImage = {binding = "love.graphics.newImage", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename", "?settings"}, ["fnl/docstring"] = "Creates a new Image from a filepath, FileData, an ImageData, or a CompressedImageData, and optionally generates or specifies mipmaps for the image.\n\nReturns -\n * image (`Image`) - A new Image object which can be drawn on screen."}}, newImageFont = {binding = "love.graphics.newImageFont", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename", "glyphs"}, ["fnl/docstring"] = "Creates a new specifically formatted image.\n\nIn versions prior to 0.9.0, L\195\150VE expects ISO 8859-1 encoding for the glyphs string.\n\nReturns -\n * font (`Font`) - A Font object which can be used to draw text on screen."}}, newMesh = {binding = "love.graphics.newMesh", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"vertices", "?mode", "?usage"}, ["fnl/docstring"] = "Creates a new Mesh.\n\nUse Mesh:setTexture if the Mesh should be textured with an Image or Canvas when it's drawn.\n\nIn versions prior to 11.0, color and byte component values were within the range of 0 to 255 instead of 0 to 1.\n\nReturns -\n * mesh (`Mesh`) - The new mesh."}}, newParticleSystem = {binding = "love.graphics.newParticleSystem", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"image", "?buffer"}, ["fnl/docstring"] = "Creates a new ParticleSystem.\n\nReturns -\n * system (`ParticleSystem`) - A new ParticleSystem."}}, newQuad = {binding = "love.graphics.newQuad", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "width", "height", "sw", "sh"}, ["fnl/docstring"] = "Creates a new Quad.\n\nThe purpose of a Quad is to use a fraction of an image to draw objects, as opposed to drawing entire image. It is most useful for sprite sheets and atlases: in a sprite atlas, multiple sprites reside in same image, quad is used to draw a specific sprite from that image; in animated sprites with all frames residing in the same image, quad is used to draw specific frame from the animation.\n\nReturns -\n * quad (`Quad`) - The new Quad."}}, newShader = {binding = "love.graphics.newShader", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"code"}, ["fnl/docstring"] = "Creates a new Shader object for hardware-accelerated vertex and pixel effects. A Shader contains either vertex shader code, pixel shader code, or both.\n\nShaders are small programs which are run on the graphics card when drawing. Vertex shaders are run once for each vertex (for example, an image has 4 vertices - one at each corner. A Mesh might have many more.) Pixel shaders are run once for each pixel on the screen which the drawn object touches. Pixel shader code is executed after all the object's vertices have been processed by the vertex shader.\n\nReturns -\n * shader (`Shader`) - A Shader object for use in drawing operations."}}, newSpriteBatch = {binding = "love.graphics.newSpriteBatch", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"image", "?maxsprites"}, ["fnl/docstring"] = "Creates a new SpriteBatch object.\n\nReturns -\n * spriteBatch (`SpriteBatch`) - The new SpriteBatch."}}, newText = {binding = "love.graphics.newText", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"font", "?textstring"}, ["fnl/docstring"] = "Creates a new drawable Text object.\n\nReturns -\n * text (`Text`) - The new drawable Text object."}}, newVideo = {binding = "love.graphics.newVideo", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new drawable Video. Currently only Ogg Theora video files are supported.\n\nReturns -\n * video (`Video`) - A new Video."}}, newVolumeImage = {binding = "love.graphics.newVolumeImage", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"layers", "?settings"}, ["fnl/docstring"] = "Creates a new volume (3D) Image.\n\nVolume images are 3D textures with width, height, and depth. They can't be rendered directly, they can only be used in Shader code (and sent to the shader via Shader:send).\n\nTo use a volume image in a Shader, it must be declared as a VolumeImage or sampler3D type (instead of Image or sampler2D). The Texel(VolumeImage image, vec3 texcoords) shader function must be used to get pixel colors from the volume image. The vec3 argument is a normalized texture coordinate with the z component representing the depth to sample at (ranging from 1).\n\nVolume images are typically used as lookup tables in shaders for color grading, for example, because sampling using a texture coordinate that is partway in between two pixels can interpolate across all 3 dimensions in the volume image, resulting in a smooth gradient even when a small-sized volume image is used as the lookup table.\n\nArray images are a much better choice than volume images for storing multiple different sprites in a single array image for directly drawing them.\n\nReturns -\n * image (`Image`) - A volume Image object."}}, origin = {binding = "love.graphics.origin", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Resets the current coordinate transformation.\n\nThis function is always used to reverse any previous calls to love.graphics.rotate, love.graphics.scale, love.graphics.shear or love.graphics.translate. It returns the current transformation state to its defaults."}}, points = {binding = "love.graphics.points", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "..."}, ["fnl/docstring"] = "Draws one or more points."}}, polygon = {binding = "love.graphics.polygon", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode", "..."}, ["fnl/docstring"] = "Draw a polygon.\n\nFollowing the mode argument, this function can accept multiple numeric arguments or a single table of numeric arguments. In either case the arguments are interpreted as alternating x and y coordinates of the polygon's vertices."}}, pop = {binding = "love.graphics.pop", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Pops the current coordinate transformation from the transformation stack.\n\nThis function is always used to reverse a previous push operation. It returns the current transformation state to what it was before the last preceding push."}}, present = {binding = "love.graphics.present", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Displays the results of drawing operations on the screen.\n\nThis function is used when writing your own love.run function. It presents all the results of your drawing operations on the screen. See the example in love.run for a typical use of this function."}}, print = {binding = "love.graphics.print", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"text", "?x", "?y", "?r", "?sx", "?sy", "?ox", "?oy", "?kx", "?ky"}, ["fnl/docstring"] = "Draws text on screen. If no Font is set, one will be created and set (once) if needed.\n\nAs of LOVE 0.7.1, when using translation and scaling functions while drawing text, this function assumes the scale occurs first.  If you don't script with this in mind, the text won't be in the right position, or possibly even on screen.\n\nlove.graphics.print and love.graphics.printf both support UTF-8 encoding. You'll also need a proper Font for special characters.\n\nIn versions prior to 11.0, color and byte component values were within the range of 0 to 255 instead of 0 to 1."}}, printf = {binding = "love.graphics.printf", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"text", "x", "y", "limit", "?align", "?r", "?sx", "?sy", "?ox", "?oy", "?kx", "?ky"}, ["fnl/docstring"] = "Draws formatted text, with word wrap and alignment.\n\nSee additional notes in love.graphics.print.\n\nThe word wrap limit is applied before any scaling, rotation, and other coordinate transformations. Therefore the amount of text per line stays constant given the same wrap limit, even if the scale arguments change.\n\nIn version 0.9.2 and earlier, wrapping was implemented by breaking up words by spaces and putting them back together to make sure things fit nicely within the limit provided. However, due to the way this is done, extra spaces between words would end up missing when printed on the screen, and some lines could overflow past the provided wrap limit. In version 0.10.0 and newer this is no longer the case.\n\nIn versions prior to 11.0, color and byte component values were within the range of 0 to 255 instead of 0 to 1."}}, push = {binding = "love.graphics.push", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Copies and pushes the current coordinate transformation to the transformation stack.\n\nThis function is always used to prepare for a corresponding pop operation later. It stores the current coordinate transformation state into the transformation stack and keeps it active. Later changes to the transformation can be undone by using the pop operation, which returns the coordinate transform to the state it was in before calling push."}}, rectangle = {binding = "love.graphics.rectangle", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode", "x", "y", "width", "height"}, ["fnl/docstring"] = "Draws a rectangle."}}, replaceTransform = {binding = "love.graphics.replaceTransform", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"transform"}, ["fnl/docstring"] = "Replaces the current coordinate transformation with the given Transform object."}}, reset = {binding = "love.graphics.reset", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Resets the current graphics settings.\n\nCalling reset makes the current drawing color white, the current background color black, disables any active color component masks, disables wireframe mode and resets the current graphics transformation to the origin. It also sets both the point and line drawing modes to smooth and their sizes to 1.0."}}, rotate = {binding = "love.graphics.rotate", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"angle"}, ["fnl/docstring"] = "Rotates the coordinate system in two dimensions.\n\nCalling this function affects all future drawing operations by rotating the coordinate system around the origin by the given amount of radians. This change lasts until love.draw() exits."}}, scale = {binding = "love.graphics.scale", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"sx", "?sy"}, ["fnl/docstring"] = "Scales the coordinate system in two dimensions.\n\nBy default the coordinate system in L\195\150VE corresponds to the display pixels in horizontal and vertical directions one-to-one, and the x-axis increases towards the right while the y-axis increases downwards. Scaling the coordinate system changes this relation.\n\nAfter scaling by sx and sy, all coordinates are treated as if they were multiplied by sx and sy. Every result of a drawing operation is also correspondingly scaled, so scaling by (2, 2) for example would mean making everything twice as large in both x- and y-directions. Scaling by a negative value flips the coordinate system in the corresponding direction, which also means everything will be drawn flipped or upside down, or both. Scaling by zero is not a useful operation.\n\nScale and translate are not commutative operations, therefore, calling them in different orders will change the outcome.\n\nScaling lasts until love.draw() exits."}}, setBackgroundColor = {binding = "love.graphics.setBackgroundColor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"red", "green", "blue", "?alpha"}, ["fnl/docstring"] = "Sets the background color."}}, setBlendMode = {binding = "love.graphics.setBlendMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode"}, ["fnl/docstring"] = "Sets the blending mode."}}, setCanvas = {binding = "love.graphics.setCanvas", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"canvas", "?mipmap"}, ["fnl/docstring"] = "Captures drawing operations to a Canvas."}}, setColor = {binding = "love.graphics.setColor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"red", "green", "blue", "?alpha"}, ["fnl/docstring"] = "Sets the color used for drawing.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1."}}, setColorMask = {binding = "love.graphics.setColorMask", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"red", "green", "blue", "alpha"}, ["fnl/docstring"] = "Sets the color mask. Enables or disables specific color components when rendering and clearing the screen. For example, if '''red''' is set to '''false''', no further changes will be made to the red component of any pixels."}}, setDefaultFilter = {binding = "love.graphics.setDefaultFilter", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"min", "?mag", "?anisotropy"}, ["fnl/docstring"] = "Sets the default scaling filters used with Images, Canvases, and Fonts."}}, setDepthMode = {binding = "love.graphics.setDepthMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"comparemode", "write"}, ["fnl/docstring"] = "Configures depth testing and writing to the depth buffer.\n\nThis is low-level functionality designed for use with custom vertex shaders and Meshes with custom vertex attributes. No higher level APIs are provided to set the depth of 2D graphics such as shapes, lines, and Images."}}, setFont = {binding = "love.graphics.setFont", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"font"}, ["fnl/docstring"] = "Set an already-loaded Font as the current font or create and load a new one from the file and size.\n\nIt's recommended that Font objects are created with love.graphics.newFont in the loading stage and then passed to this function in the drawing stage."}}, setFrontFaceWinding = {binding = "love.graphics.setFrontFaceWinding", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"winding"}, ["fnl/docstring"] = "Sets whether triangles with clockwise- or counterclockwise-ordered vertices are considered front-facing.\n\nThis is designed for use in combination with Mesh face culling. Other love.graphics shapes, lines, and sprites are not guaranteed to have a specific winding order to their internal vertices."}}, setLineJoin = {binding = "love.graphics.setLineJoin", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"join"}, ["fnl/docstring"] = "Sets the line join style. See LineJoin for the possible options."}}, setLineStyle = {binding = "love.graphics.setLineStyle", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"style"}, ["fnl/docstring"] = "Sets the line style."}}, setLineWidth = {binding = "love.graphics.setLineWidth", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"width"}, ["fnl/docstring"] = "Sets the line width."}}, setMeshCullMode = {binding = "love.graphics.setMeshCullMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"mode"}, ["fnl/docstring"] = "Sets whether back-facing triangles in a Mesh are culled.\n\nThis is designed for use with low level custom hardware-accelerated 3D rendering via custom vertex attributes on Meshes, custom vertex shaders, and depth testing with a depth buffer.\n\nBy default, both front- and back-facing triangles in Meshes are rendered."}}, setNewFont = {binding = "love.graphics.setNewFont", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?size"}, ["fnl/docstring"] = "Creates and sets a new Font.\n\nReturns -\n * font (`Font`) - The new font."}}, setPointSize = {binding = "love.graphics.setPointSize", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"size"}, ["fnl/docstring"] = "Sets the point size."}}, setScissor = {binding = "love.graphics.setScissor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "width", "height"}, ["fnl/docstring"] = "Sets or disables scissor.\n\nThe scissor limits the drawing area to a specified rectangle. This affects all graphics calls, including love.graphics.clear. \n\nThe dimensions of the scissor is unaffected by graphical transformations (translate, scale, ...)."}}, setShader = {binding = "love.graphics.setShader", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"shader"}, ["fnl/docstring"] = "Sets or resets a Shader as the current pixel effect or vertex shaders. All drawing operations until the next ''love.graphics.setShader'' will be drawn using the Shader object specified."}}, setStencilTest = {binding = "love.graphics.setStencilTest", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"comparemode", "comparevalue"}, ["fnl/docstring"] = "Configures or disables stencil testing.\n\nWhen stencil testing is enabled, the geometry of everything that is drawn afterward will be clipped / stencilled out based on a comparison between the arguments of this function and the stencil value of each pixel that the geometry touches. The stencil values of pixels are affected via love.graphics.stencil."}}, setWireframe = {binding = "love.graphics.setWireframe", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Sets whether wireframe lines will be used when drawing."}}, shear = {binding = "love.graphics.shear", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"kx", "ky"}, ["fnl/docstring"] = "Shears the coordinate system."}}, stencil = {binding = "love.graphics.stencil", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"stencilfunction", "?action", "?value", "?keepvalues"}, ["fnl/docstring"] = "Draws geometry as a stencil.\n\nThe geometry drawn by the supplied function sets invisible stencil values of pixels, instead of setting pixel colors. The stencil buffer (which contains those stencil values) can act like a mask / stencil - love.graphics.setStencilTest can be used afterward to determine how further rendering is affected by the stencil values in each pixel.\n\nStencil values are integers within the range of 255."}}, transformPoint = {binding = "love.graphics.transformPoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"globalX", "globalY"}, ["fnl/docstring"] = "Converts the given 2D position from global coordinates into screen-space.\n\nThis effectively applies the current graphics transformations to the given position. A similar Transform:transformPoint method exists for Transform objects.\n\nReturns -\n * screenX (`number`) - The x component of the position with graphics transformations applied.\n * screenY (`number`) - The y component of the position with graphics transformations applied."}}, translate = {binding = "love.graphics.translate", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"dx", "dy"}, ["fnl/docstring"] = "Translates the coordinate system in two dimensions.\n\nWhen this function is called with two numbers, dx, and dy, all the following drawing operations take effect as if their x and y coordinates were x+dx and y+dy. \n\nScale and translate are not commutative operations, therefore, calling them in different orders will change the outcome.\n\nThis change lasts until love.draw() exits or else a love.graphics.pop reverts to a previous love.graphics.push.\n\nTranslating using whole numbers will prevent tearing/blurring of images and fonts draw after translating."}}, validateShader = {binding = "love.graphics.validateShader", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"gles", "code"}, ["fnl/docstring"] = "Validates shader code. Check if specified shader code does not contain any errors.\n\nReturns -\n * status (`boolean`) - true if specified shader code doesn't contain any errors. false otherwise.\n * message (`string`) - Reason why shader code validation failed (or nil if validation succeded)."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "The primary responsibility for the love.graphics module is the drawing of lines, shapes, text, Images and other Drawable objects onto the screen. Its secondary responsibilities include loading external files (including Images and Fonts) into memory, creating specialized objects (such as ParticleSystems or Canvases) and managing screen geometry.\n\nL\195\150VE's coordinate system is rooted in the upper-left corner of the screen, which is at location (0, 0). The x axis is horizontal: larger values are further to the right. The y axis is vertical: larger values are further towards the bottom.\n\nIn many cases, you draw images or shapes in terms of their upper-left corner.\n\nMany of the functions are used to manipulate the graphics coordinate system, which is essentially the way coordinates are mapped to the display. You can change the position, scale, and even rotation in this way."}}, image = {binding = "love.image", fields = {isCompressed = {binding = "love.image.isCompressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Determines whether a file can be loaded as CompressedImageData.\n\nReturns -\n * compressed (`boolean`) - Whether the file can be loaded as CompressedImageData or not."}}, newCompressedData = {binding = "love.image.newCompressedData", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Create a new CompressedImageData object from a compressed image file. L\195\150VE supports several compressed texture formats, enumerated in the CompressedImageFormat page.\n\nReturns -\n * compressedImageData (`CompressedImageData`) - The new CompressedImageData object."}}, newImageData = {binding = "love.image.newImageData", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"width", "height"}, ["fnl/docstring"] = "Creates a new ImageData object.\n\nReturns -\n * imageData (`ImageData`) - The new blank ImageData object. Each pixel's color values, (including the alpha values!) will be set to zero."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to decode encoded image data."}}, joystick = {binding = "love.joystick", fields = {getGamepadMappingString = {binding = "love.joystick.getGamepadMappingString", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"guid"}, ["fnl/docstring"] = "Gets the full gamepad mapping string of the Joysticks which have the given GUID, or nil if the GUID isn't recognized as a gamepad.\n\nThe mapping string contains binding information used to map the Joystick's buttons an axes to the standard gamepad layout, and can be used later with love.joystick.loadGamepadMappings.\n\nReturns -\n * mappingstring (`string`) - A string containing the Joystick's gamepad mappings, or nil if the GUID is not recognized as a gamepad."}}, getJoystickCount = {binding = "love.joystick.getJoystickCount", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the number of connected joysticks.\n\nReturns -\n * joystickcount (`number`) - The number of connected joysticks."}}, getJoysticks = {binding = "love.joystick.getJoysticks", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets a list of connected Joysticks.\n\nReturns -\n * joysticks (`table`) - The list of currently connected Joysticks."}}, loadGamepadMappings = {binding = "love.joystick.loadGamepadMappings", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Loads a gamepad mappings string or file created with love.joystick.saveGamepadMappings.\n\nIt also recognizes any SDL gamecontroller mapping string, such as those created with Steam's Big Picture controller configure interface, or this nice database. If a new mapping is loaded for an already known controller GUID, the later version will overwrite the one currently loaded."}}, saveGamepadMappings = {binding = "love.joystick.saveGamepadMappings", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Saves the virtual gamepad mappings of all recognized as gamepads and have either been recently used or their gamepad bindings have been modified.\n\nThe mappings are stored as a string for use with love.joystick.loadGamepadMappings.\n\nReturns -\n * mappings (`string`) - The mappings string that was written to the file."}}, setGamepadMapping = {binding = "love.joystick.setGamepadMapping", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"guid", "button", "inputtype", "inputindex", "?hatdir"}, ["fnl/docstring"] = "Binds a virtual gamepad input to a button, axis or hat for all Joysticks of a certain type. For example, if this function is used with a GUID returned by a Dualshock 3 controller in OS X, the binding will affect Joystick:getGamepadAxis and Joystick:isGamepadDown for ''all'' Dualshock 3 controllers used with the game when run in OS X.\n\nL\195\150VE includes built-in gamepad bindings for many common controllers. This function lets you change the bindings or add new ones for types of Joysticks which aren't recognized as gamepads by default.\n\nThe virtual gamepad buttons and axes are designed around the Xbox 360 controller layout.\n\nReturns -\n * success (`boolean`) - Whether the virtual gamepad button was successfully bound."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to the user's joystick."}}, joystickadded = {binding = "love.joystickadded", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick"}, ["fnl/docstring"] = "Called when a Joystick is connected."}}, joystickaxis = {binding = "love.joystickaxis", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "axis", "value"}, ["fnl/docstring"] = "Called when a joystick axis moves."}}, joystickhat = {binding = "love.joystickhat", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "hat", "direction"}, ["fnl/docstring"] = "Called when a joystick hat direction changes."}}, joystickpressed = {binding = "love.joystickpressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "button"}, ["fnl/docstring"] = "Called when a joystick button is pressed."}}, joystickreleased = {binding = "love.joystickreleased", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick", "button"}, ["fnl/docstring"] = "Called when a joystick button is released."}}, joystickremoved = {binding = "love.joystickremoved", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joystick"}, ["fnl/docstring"] = "Called when a Joystick is disconnected."}}, keyboard = {binding = "love.keyboard", fields = {getKeyFromScancode = {binding = "love.keyboard.getKeyFromScancode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"scancode"}, ["fnl/docstring"] = "Gets the key corresponding to the given hardware scancode.\n\nUnlike key constants, Scancodes are keyboard layout-independent. For example the scancode 'w' will be generated if the key in the same place as the 'w' key on an American keyboard is pressed, no matter what the key is labelled or what the user's operating system settings are.\n\nScancodes are useful for creating default controls that have the same physical locations on on all systems.\n\nReturns -\n * key (`KeyConstant`) - The key corresponding to the given scancode, or 'unknown' if the scancode doesn't map to a KeyConstant on the current system."}}, getScancodeFromKey = {binding = "love.keyboard.getScancodeFromKey", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"key"}, ["fnl/docstring"] = "Gets the hardware scancode corresponding to the given key.\n\nUnlike key constants, Scancodes are keyboard layout-independent. For example the scancode 'w' will be generated if the key in the same place as the 'w' key on an American keyboard is pressed, no matter what the key is labelled or what the user's operating system settings are.\n\nScancodes are useful for creating default controls that have the same physical locations on on all systems.\n\nReturns -\n * scancode (`Scancode`) - The scancode corresponding to the given key, or 'unknown' if the given key has no known physical representation on the current system."}}, hasKeyRepeat = {binding = "love.keyboard.hasKeyRepeat", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether key repeat is enabled.\n\nReturns -\n * enabled (`boolean`) - Whether key repeat is enabled."}}, hasScreenKeyboard = {binding = "love.keyboard.hasScreenKeyboard", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether screen keyboard is supported.\n\nReturns -\n * supported (`boolean`) - Whether screen keyboard is supported."}}, hasTextInput = {binding = "love.keyboard.hasTextInput", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether text input events are enabled.\n\nReturns -\n * enabled (`boolean`) - Whether text input events are enabled."}}, isDown = {binding = "love.keyboard.isDown", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"key"}, ["fnl/docstring"] = "Checks whether a certain key is down. Not to be confused with love.keypressed or love.keyreleased.\n\nReturns -\n * down (`boolean`) - True if the key is down, false if not."}}, isScancodeDown = {binding = "love.keyboard.isScancodeDown", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"scancode", "..."}, ["fnl/docstring"] = "Checks whether the specified Scancodes are pressed. Not to be confused with love.keypressed or love.keyreleased.\n\nUnlike regular KeyConstants, Scancodes are keyboard layout-independent. The scancode 'w' is used if the key in the same place as the 'w' key on an American keyboard is pressed, no matter what the key is labelled or what the user's operating system settings are.\n\nReturns -\n * down (`boolean`) - True if any supplied Scancode is down, false if not."}}, setKeyRepeat = {binding = "love.keyboard.setKeyRepeat", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Enables or disables key repeat for love.keypressed. It is disabled by default."}}, setTextInput = {binding = "love.keyboard.setTextInput", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Enables or disables text input events. It is enabled by default on Windows, Mac, and Linux, and disabled by default on iOS and Android.\n\nOn touch devices, this shows the system's native on-screen keyboard when it's enabled."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to the user's keyboard."}}, keypressed = {binding = "love.keypressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"key", "scancode", "isrepeat"}, ["fnl/docstring"] = "Callback function triggered when a key is pressed."}}, keyreleased = {binding = "love.keyreleased", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"key", "scancode"}, ["fnl/docstring"] = "Callback function triggered when a keyboard key is released."}}, load = {binding = "love.load", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"arg", "unfilteredArg"}, ["fnl/docstring"] = "This function is called exactly once at the beginning of the game."}}, lowmemory = {binding = "love.lowmemory", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Callback function triggered when the system is running out of memory on mobile devices.\n\nMobile operating systems may forcefully kill the game if it uses too much memory, so any non-critical resource should be removed if possible (by setting all variables referencing the resources to '''nil'''), when this event is triggered. Sounds and images in particular tend to use the most memory."}}, math = {binding = "love.math", fields = {colorFromBytes = {binding = "love.math.colorFromBytes", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"rb", "gb", "bb", "?ab"}, ["fnl/docstring"] = "Converts a color from 0..255 to 0..1 range.\n\nReturns -\n * r (`number`) - Red color component in 0..1 range.\n * g (`number`) - Green color component in 0..1 range.\n * b (`number`) - Blue color component in 0..1 range.\n * a (`number`) - Alpha color component in 0..1 range or nil if alpha is not specified."}}, colorToBytes = {binding = "love.math.colorToBytes", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"r", "g", "b", "?a"}, ["fnl/docstring"] = "Converts a color from 0..1 to 0..255 range.\n\nReturns -\n * rb (`number`) - Red color component in 0..255 range.\n * gb (`number`) - Green color component in 0..255 range.\n * bb (`number`) - Blue color component in 0..255 range.\n * ab (`number`) - Alpha color component in 0..255 range or nil if alpha is not specified."}}, gammaToLinear = {binding = "love.math.gammaToLinear", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"r", "g", "b"}, ["fnl/docstring"] = "Converts a color from gamma-space (sRGB) to linear-space (RGB). This is useful when doing gamma-correct rendering and you need to do math in linear RGB in the few cases where L\195\150VE doesn't handle conversions automatically.\n\nRead more about gamma-correct rendering here, here, and here.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1.\n\nReturns -\n * lr (`number`) - The red channel of the converted color in linear RGB space.\n * lg (`number`) - The green channel of the converted color in linear RGB space.\n * lb (`number`) - The blue channel of the converted color in linear RGB space."}}, getRandomSeed = {binding = "love.math.getRandomSeed", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the seed of the random number generator.\n\nThe seed is split into two numbers due to Lua's use of doubles for all number values - doubles can't accurately represent integer  values above 2^53, but the seed can be an integer value up to 2^64.\n\nReturns -\n * low (`number`) - Integer number representing the lower 32 bits of the random number generator's 64 bit seed value.\n * high (`number`) - Integer number representing the higher 32 bits of the random number generator's 64 bit seed value."}}, getRandomState = {binding = "love.math.getRandomState", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current state of the random number generator. This returns an opaque implementation-dependent string which is only useful for later use with love.math.setRandomState or RandomGenerator:setState.\n\nThis is different from love.math.getRandomSeed in that getRandomState gets the random number generator's current state, whereas getRandomSeed gets the previously set seed number.\n\nReturns -\n * state (`string`) - The current state of the random number generator, represented as a string."}}, isConvex = {binding = "love.math.isConvex", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"vertices"}, ["fnl/docstring"] = "Checks whether a polygon is convex.\n\nPolygonShapes in love.physics, some forms of Meshes, and polygons drawn with love.graphics.polygon must be simple convex polygons.\n\nReturns -\n * convex (`boolean`) - Whether the given polygon is convex."}}, linearToGamma = {binding = "love.math.linearToGamma", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"lr", "lg", "lb"}, ["fnl/docstring"] = "Converts a color from linear-space (RGB) to gamma-space (sRGB). This is useful when storing linear RGB color values in an image, because the linear RGB color space has less precision than sRGB for dark colors, which can result in noticeable color banding when drawing.\n\nIn general, colors chosen based on what they look like on-screen are already in gamma-space and should not be double-converted. Colors calculated using math are often in the linear RGB space.\n\nRead more about gamma-correct rendering here, here, and here.\n\nIn versions prior to 11.0, color component values were within the range of 0 to 255 instead of 0 to 1.\n\nReturns -\n * cr (`number`) - The red channel of the converted color in gamma sRGB space.\n * cg (`number`) - The green channel of the converted color in gamma sRGB space.\n * cb (`number`) - The blue channel of the converted color in gamma sRGB space."}}, newBezierCurve = {binding = "love.math.newBezierCurve", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"vertices"}, ["fnl/docstring"] = "Creates a new BezierCurve object.\n\nThe number of vertices in the control polygon determines the degree of the curve, e.g. three vertices define a quadratic (degree 2) B\195\169zier curve, four vertices define a cubic (degree 3) B\195\169zier curve, etc.\n\nReturns -\n * curve (`BezierCurve`) - A B\195\169zier curve object."}}, newRandomGenerator = {binding = "love.math.newRandomGenerator", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Creates a new RandomGenerator object which is completely independent of other RandomGenerator objects and random functions.\n\nReturns -\n * rng (`RandomGenerator`) - The new Random Number Generator object."}}, newTransform = {binding = "love.math.newTransform", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Creates a new Transform object.\n\nReturns -\n * transform (`Transform`) - The new Transform object."}}, noise = {binding = "love.math.noise", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x"}, ["fnl/docstring"] = "Generates a Simplex or Perlin noise value in 1-4 dimensions. The return value will always be the same, given the same arguments.\n\nSimplex noise is closely related to Perlin noise. It is widely used for procedural content generation.\n\nThere are many webpages which discuss Perlin and Simplex noise in detail.\n\nReturns -\n * value (`number`) - The noise value in the range of 1."}}, random = {binding = "love.math.random", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Generates a pseudo-random number in a platform independent manner. The default love.run seeds this function at startup, so you generally don't need to seed it yourself.\n\nReturns -\n * number (`number`) - The pseudo-random number."}}, randomNormal = {binding = "love.math.randomNormal", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?stddev", "?mean"}, ["fnl/docstring"] = "Get a normally distributed pseudo random number.\n\nReturns -\n * number (`number`) - Normally distributed random number with variance (stddev)\194\178 and the specified mean."}}, setRandomSeed = {binding = "love.math.setRandomSeed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"seed"}, ["fnl/docstring"] = "Sets the seed of the random number generator using the specified integer number. This is called internally at startup, so you generally don't need to call it yourself."}}, setRandomState = {binding = "love.math.setRandomState", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"state"}, ["fnl/docstring"] = "Sets the current state of the random number generator. The value used as an argument for this function is an opaque implementation-dependent string and should only originate from a previous call to love.math.getRandomState.\n\nThis is different from love.math.setRandomSeed in that setRandomState directly sets the random number generator's current implementation-dependent state, whereas setRandomSeed gives it a new seed value."}}, triangulate = {binding = "love.math.triangulate", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"polygon"}, ["fnl/docstring"] = "Decomposes a simple convex or concave polygon into triangles.\n\nReturns -\n * triangles (`table`) - List of triangles the polygon is composed of, in the form of {{x1, y1, x2, y2, x3, y3},  {x1, y1, x2, y2, x3, y3}, ...}."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides system-independent mathematical functions."}}, mouse = {binding = "love.mouse", fields = {getCursor = {binding = "love.mouse.getCursor", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current Cursor.\n\nReturns -\n * cursor (`Cursor`) - The current cursor, or nil if no cursor is set."}}, getPosition = {binding = "love.mouse.getPosition", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the current position of the mouse.\n\nReturns -\n * x (`number`) - The position of the mouse along the x-axis.\n * y (`number`) - The position of the mouse along the y-axis."}}, getRelativeMode = {binding = "love.mouse.getRelativeMode", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether relative mode is enabled for the mouse.\n\nIf relative mode is enabled, the cursor is hidden and doesn't move when the mouse does, but relative mouse motion events are still generated via love.mousemoved. This lets the mouse move in any direction indefinitely without the cursor getting stuck at the edges of the screen.\n\nThe reported position of the mouse is not updated while relative mode is enabled, even when relative mouse motion events are generated.\n\nReturns -\n * enabled (`boolean`) - True if relative mode is enabled, false if it's disabled."}}, getSystemCursor = {binding = "love.mouse.getSystemCursor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"ctype"}, ["fnl/docstring"] = "Gets a Cursor object representing a system-native hardware cursor.\n\nHardware cursors are framerate-independent and work the same way as normal operating system cursors. Unlike drawing an image at the mouse's current coordinates, hardware cursors never have visible lag between when the mouse is moved and when the cursor position updates, even at low framerates.\n\nReturns -\n * cursor (`Cursor`) - The Cursor object representing the system cursor type."}}, getX = {binding = "love.mouse.getX", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the current x-position of the mouse.\n\nReturns -\n * x (`number`) - The position of the mouse along the x-axis."}}, getY = {binding = "love.mouse.getY", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the current y-position of the mouse.\n\nReturns -\n * y (`number`) - The position of the mouse along the y-axis."}}, isCursorSupported = {binding = "love.mouse.isCursorSupported", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether cursor functionality is supported.\n\nIf it isn't supported, calling love.mouse.newCursor and love.mouse.getSystemCursor will cause an error. Mobile devices do not support cursors.\n\nReturns -\n * supported (`boolean`) - Whether the system has cursor functionality."}}, isDown = {binding = "love.mouse.isDown", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"button", "..."}, ["fnl/docstring"] = "Checks whether a certain mouse button is down.\n\nThis function does not detect mouse wheel scrolling; you must use the love.wheelmoved (or love.mousepressed in version 0.9.2 and older) callback for that. \n\nReturns -\n * down (`boolean`) - True if any specified button is down."}}, isGrabbed = {binding = "love.mouse.isGrabbed", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the mouse is grabbed.\n\nReturns -\n * grabbed (`boolean`) - True if the cursor is grabbed, false if it is not."}}, isVisible = {binding = "love.mouse.isVisible", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the cursor is visible.\n\nReturns -\n * visible (`boolean`) - True if the cursor to visible, false if the cursor is hidden."}}, newCursor = {binding = "love.mouse.newCursor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"imageData", "?hotx", "?hoty"}, ["fnl/docstring"] = "Creates a new hardware Cursor object from an image file or ImageData.\n\nHardware cursors are framerate-independent and work the same way as normal operating system cursors. Unlike drawing an image at the mouse's current coordinates, hardware cursors never have visible lag between when the mouse is moved and when the cursor position updates, even at low framerates.\n\nThe hot spot is the point the operating system uses to determine what was clicked and at what position the mouse cursor is. For example, the normal arrow pointer normally has its hot spot at the top left of the image, but a crosshair cursor might have it in the middle.\n\nReturns -\n * cursor (`Cursor`) - The new Cursor object."}}, setCursor = {binding = "love.mouse.setCursor", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"cursor"}, ["fnl/docstring"] = "Sets the current mouse cursor."}}, setGrabbed = {binding = "love.mouse.setGrabbed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"grab"}, ["fnl/docstring"] = "Grabs the mouse and confines it to the window."}}, setPosition = {binding = "love.mouse.setPosition", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y"}, ["fnl/docstring"] = "Sets the current position of the mouse. Non-integer values are floored."}}, setRelativeMode = {binding = "love.mouse.setRelativeMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Sets whether relative mode is enabled for the mouse.\n\nWhen relative mode is enabled, the cursor is hidden and doesn't move when the mouse does, but relative mouse motion events are still generated via love.mousemoved. This lets the mouse move in any direction indefinitely without the cursor getting stuck at the edges of the screen.\n\nThe reported position of the mouse may not be updated while relative mode is enabled, even when relative mouse motion events are generated."}}, setVisible = {binding = "love.mouse.setVisible", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"visible"}, ["fnl/docstring"] = "Sets the current visibility of the cursor."}}, setX = {binding = "love.mouse.setX", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x"}, ["fnl/docstring"] = "Sets the current X position of the mouse.\n\nNon-integer values are floored."}}, setY = {binding = "love.mouse.setY", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"y"}, ["fnl/docstring"] = "Sets the current Y position of the mouse.\n\nNon-integer values are floored."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to the user's mouse."}}, mousefocus = {binding = "love.mousefocus", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"focus"}, ["fnl/docstring"] = "Callback function triggered when window receives or loses mouse focus."}}, mousemoved = {binding = "love.mousemoved", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "dx", "dy", "istouch"}, ["fnl/docstring"] = "Callback function triggered when the mouse is moved."}}, mousepressed = {binding = "love.mousepressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "button", "istouch", "presses"}, ["fnl/docstring"] = "Callback function triggered when a mouse button is pressed."}}, mousereleased = {binding = "love.mousereleased", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "button", "istouch", "presses"}, ["fnl/docstring"] = "Callback function triggered when a mouse button is released."}}, physics = {binding = "love.physics", fields = {getDistance = {binding = "love.physics.getDistance", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"fixture1", "fixture2"}, ["fnl/docstring"] = "Returns the two closest points between two fixtures and their distance.\n\nReturns -\n * distance (`number`) - The distance of the two points.\n * x1 (`number`) - The x-coordinate of the first point.\n * y1 (`number`) - The y-coordinate of the first point.\n * x2 (`number`) - The x-coordinate of the second point.\n * y2 (`number`) - The y-coordinate of the second point."}}, getMeter = {binding = "love.physics.getMeter", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the meter scale factor.\n\nAll coordinates in the physics module are divided by this number, creating a convenient way to draw the objects directly to the screen without the need for graphics transformations.\n\nIt is recommended to create shapes no larger than 10 times the scale. This is important because Box2D is tuned to work well with shape sizes from 0.1 to 10 meters.\n\nReturns -\n * scale (`number`) - The scale factor as an integer."}}, newBody = {binding = "love.physics.newBody", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"world", "?x", "?y", "?type"}, ["fnl/docstring"] = "Creates a new body.\n\nThere are three types of bodies. \n\n* Static bodies do not move, have a infinite mass, and can be used for level boundaries. \n\n* Dynamic bodies are the main actors in the simulation, they collide with everything. \n\n* Kinematic bodies do not react to forces and only collide with dynamic bodies.\n\nThe mass of the body gets calculated when a Fixture is attached or removed, but can be changed at any time with Body:setMass or Body:resetMassData.\n\nReturns -\n * body (`Body`) - A new body."}}, newChainShape = {binding = "love.physics.newChainShape", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"loop", "x1", "y1", "x2", "y2", "..."}, ["fnl/docstring"] = "Creates a new ChainShape.\n\nReturns -\n * shape (`ChainShape`) - The new shape."}}, newCircleShape = {binding = "love.physics.newCircleShape", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"radius"}, ["fnl/docstring"] = "Creates a new CircleShape.\n\nReturns -\n * shape (`CircleShape`) - The new shape."}}, newDistanceJoint = {binding = "love.physics.newDistanceJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x1", "y1", "x2", "y2", "?collideConnected"}, ["fnl/docstring"] = "Creates a DistanceJoint between two bodies.\n\nThis joint constrains the distance between two points on two bodies to be constant. These two points are specified in world coordinates and the two bodies are assumed to be in place when this joint is created. The first anchor point is connected to the first body and the second to the second body, and the points define the length of the distance joint.\n\nReturns -\n * joint (`DistanceJoint`) - The new distance joint."}}, newEdgeShape = {binding = "love.physics.newEdgeShape", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x1", "y1", "x2", "y2"}, ["fnl/docstring"] = "Creates a new EdgeShape.\n\nReturns -\n * shape (`EdgeShape`) - The new shape."}}, newFixture = {binding = "love.physics.newFixture", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body", "shape", "?density"}, ["fnl/docstring"] = "Creates and attaches a Fixture to a body.\n\nNote that the Shape object is copied rather than kept as a reference when the Fixture is created. To get the Shape object that the Fixture owns, use Fixture:getShape.\n\nReturns -\n * fixture (`Fixture`) - The new fixture."}}, newFrictionJoint = {binding = "love.physics.newFrictionJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x", "y", "?collideConnected"}, ["fnl/docstring"] = "Create a friction joint between two bodies. A FrictionJoint applies friction to a body.\n\nReturns -\n * joint (`FrictionJoint`) - The new FrictionJoint."}}, newGearJoint = {binding = "love.physics.newGearJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"joint1", "joint2", "?ratio", "?collideConnected"}, ["fnl/docstring"] = "Create a GearJoint connecting two Joints.\n\nThe gear joint connects two joints that must be either  prismatic or  revolute joints. Using this joint requires that the joints it uses connect their respective bodies to the ground and have the ground as the first body. When destroying the bodies and joints you must make sure you destroy the gear joint before the other joints.\n\nThe gear joint has a ratio the determines how the angular or distance values of the connected joints relate to each other. The formula coordinate1 + ratio * coordinate2 always has a constant value that is set when the gear joint is created.\n\nReturns -\n * joint (`GearJoint`) - The new gear joint."}}, newMotorJoint = {binding = "love.physics.newMotorJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "?correctionFactor"}, ["fnl/docstring"] = "Creates a joint between two bodies which controls the relative motion between them.\n\nPosition and rotation offsets can be specified once the MotorJoint has been created, as well as the maximum motor force and torque that will be be applied to reach the target offsets.\n\nReturns -\n * joint (`MotorJoint`) - The new MotorJoint."}}, newMouseJoint = {binding = "love.physics.newMouseJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body", "x", "y"}, ["fnl/docstring"] = "Create a joint between a body and the mouse.\n\nThis joint actually connects the body to a fixed point in the world. To make it follow the mouse, the fixed point must be updated every timestep (example below).\n\nThe advantage of using a MouseJoint instead of just changing a body position directly is that collisions and reactions to other joints are handled by the physics engine. \n\nReturns -\n * joint (`MouseJoint`) - The new mouse joint."}}, newPolygonShape = {binding = "love.physics.newPolygonShape", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x1", "y1", "x2", "y2", "x3", "y3", "..."}, ["fnl/docstring"] = "Creates a new PolygonShape.\n\nThis shape can have 8 vertices at most, and must form a convex shape.\n\nReturns -\n * shape (`PolygonShape`) - A new PolygonShape."}}, newPrismaticJoint = {binding = "love.physics.newPrismaticJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x", "y", "ax", "ay", "?collideConnected"}, ["fnl/docstring"] = "Creates a PrismaticJoint between two bodies.\n\nA prismatic joint constrains two bodies to move relatively to each other on a specified axis. It does not allow for relative rotation. Its definition and operation are similar to a  revolute joint, but with translation and force substituted for angle and torque.\n\nReturns -\n * joint (`PrismaticJoint`) - The new prismatic joint."}}, newPulleyJoint = {binding = "love.physics.newPulleyJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "gx1", "gy1", "gx2", "gy2", "x1", "y1", "x2", "y2", "?ratio", "?collideConnected"}, ["fnl/docstring"] = "Creates a PulleyJoint to join two bodies to each other and the ground.\n\nThe pulley joint simulates a pulley with an optional block and tackle. If the ratio parameter has a value different from one, then the simulated rope extends faster on one side than the other. In a pulley joint the total length of the simulated rope is the constant length1 + ratio * length2, which is set when the pulley joint is created.\n\nPulley joints can behave unpredictably if one side is fully extended. It is recommended that the method  setMaxLengths\194\160 be used to constrain the maximum lengths each side can attain.\n\nReturns -\n * joint (`PulleyJoint`) - The new pulley joint."}}, newRectangleShape = {binding = "love.physics.newRectangleShape", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"width", "height"}, ["fnl/docstring"] = "Shorthand for creating rectangular PolygonShapes. \n\nBy default, the local origin is located at the '''center''' of the rectangle as opposed to the top left for graphics.\n\nReturns -\n * shape (`PolygonShape`) - A new PolygonShape."}}, newRevoluteJoint = {binding = "love.physics.newRevoluteJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x", "y", "?collideConnected"}, ["fnl/docstring"] = "Creates a pivot joint between two bodies.\n\nThis joint connects two bodies to a point around which they can pivot.\n\nReturns -\n * joint (`RevoluteJoint`) - The new revolute joint."}}, newRopeJoint = {binding = "love.physics.newRopeJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x1", "y1", "x2", "y2", "maxLength", "?collideConnected"}, ["fnl/docstring"] = "Creates a joint between two bodies. Its only function is enforcing a max distance between these bodies.\n\nReturns -\n * joint (`RopeJoint`) - The new RopeJoint."}}, newWeldJoint = {binding = "love.physics.newWeldJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x", "y", "?collideConnected"}, ["fnl/docstring"] = "Creates a constraint joint between two bodies. A WeldJoint essentially glues two bodies together. The constraint is a bit soft, however, due to Box2D's iterative solver.\n\nReturns -\n * joint (`WeldJoint`) - The new WeldJoint."}}, newWheelJoint = {binding = "love.physics.newWheelJoint", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"body1", "body2", "x", "y", "ax", "ay", "?collideConnected"}, ["fnl/docstring"] = "Creates a wheel joint.\n\nReturns -\n * joint (`WheelJoint`) - The new WheelJoint."}}, newWorld = {binding = "love.physics.newWorld", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?xg", "?yg", "?sleep"}, ["fnl/docstring"] = "Creates a new World.\n\nReturns -\n * world (`World`) - A brave new World."}}, setMeter = {binding = "love.physics.setMeter", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"scale"}, ["fnl/docstring"] = "Sets the pixels to meter scale factor.\n\nAll coordinates in the physics module are divided by this number and converted to meters, and it creates a convenient way to draw the objects directly to the screen without the need for graphics transformations.\n\nIt is recommended to create shapes no larger than 10 times the scale. This is important because Box2D is tuned to work well with shape sizes from 0.1 to 10 meters. The default meter scale is 30."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Can simulate 2D rigid body physics in a realistic manner. This module is based on Box2D, and this API corresponds to the Box2D API as closely as possible."}}, quit = {binding = "love.quit", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Callback function triggered when the game is closed.\n\nReturns -\n * r (`boolean`) - Abort quitting. If true, do not close the game."}}, resize = {binding = "love.resize", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"w", "h"}, ["fnl/docstring"] = "Called when the window is resized, for example if the user resizes the window, or if love.window.setMode is called with an unsupported width or height in fullscreen and the window chooses the closest appropriate size."}}, run = {binding = "love.run", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "The main function, containing the main loop. A sensible default is used when left out.\n\nReturns -\n * mainLoop (`function`) - Function which handlers one frame, including events and rendering when called."}}, sound = {binding = "love.sound", fields = {newDecoder = {binding = "love.sound.newDecoder", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"file", "?buffer"}, ["fnl/docstring"] = "Attempts to find a decoder for the encoded sound data in the specified file.\n\nReturns -\n * decoder (`Decoder`) - A new Decoder object."}}, newSoundData = {binding = "love.sound.newSoundData", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates new SoundData from a filepath, File, or Decoder. It's also possible to create SoundData with a custom sample rate, channel and bit depth.\n\nThe sound data will be decoded to the memory in a raw format. It is recommended to create only short sounds like effects, as a 3 minute song uses 30 MB of memory this way.\n\nReturns -\n * soundData (`SoundData`) - A new SoundData object."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "This module is responsible for decoding sound files. It can't play the sounds, see love.audio for that."}}, system = {binding = "love.system", fields = {getClipboardText = {binding = "love.system.getClipboardText", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets text from the clipboard.\n\nReturns -\n * text (`string`) - The text currently held in the system's clipboard."}}, getOS = {binding = "love.system.getOS", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the current operating system. In general, L\195\150VE abstracts away the need to know the current operating system, but there are a few cases where it can be useful (especially in combination with os.execute.)\n\nReturns -\n * osString (`string`) - The current operating system. 'OS X', 'Windows', 'Linux', 'Android' or 'iOS'."}}, getPowerInfo = {binding = "love.system.getPowerInfo", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets information about the system's power supply.\n\nReturns -\n * state (`PowerState`) - The basic state of the power supply.\n * percent (`number`) - Percentage of battery life left, between 0 and 100. nil if the value can't be determined or there's no battery.\n * seconds (`number`) - Seconds of battery life left. nil if the value can't be determined or there's no battery."}}, getProcessorCount = {binding = "love.system.getProcessorCount", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the amount of logical processor in the system.\n\nReturns -\n * processorCount (`number`) - Amount of logical processors."}}, hasBackgroundMusic = {binding = "love.system.hasBackgroundMusic", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether another application on the system is playing music in the background.\n\nCurrently this is implemented on iOS and Android, and will always return false on other operating systems. The t.audio.mixwithsystem flag in love.conf can be used to configure whether background audio / music from other apps should play while L\195\150VE is open.\n\nReturns -\n * backgroundmusic (`boolean`) - True if the user is playing music in the background via another app, false otherwise."}}, openURL = {binding = "love.system.openURL", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"url"}, ["fnl/docstring"] = "Opens a URL with the user's web or file browser.\n\nReturns -\n * success (`boolean`) - Whether the URL was opened successfully."}}, setClipboardText = {binding = "love.system.setClipboardText", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"text"}, ["fnl/docstring"] = "Puts text in the clipboard."}}, vibrate = {binding = "love.system.vibrate", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?seconds"}, ["fnl/docstring"] = "Causes the device to vibrate, if possible. Currently this will only work on Android and iOS devices that have a built-in vibration motor."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides access to information about the user's system."}}, textedited = {binding = "love.textedited", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"text", "start", "length"}, ["fnl/docstring"] = "Called when the candidate text for an IME (Input Method Editor) has changed.\n\nThe candidate text is not the final text that the user will eventually choose. Use love.textinput for that."}}, textinput = {binding = "love.textinput", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"text"}, ["fnl/docstring"] = "Called when text has been entered by the user. For example if shift-2 is pressed on an American keyboard layout, the text '@' will be generated."}}, thread = {binding = "love.thread", fields = {getChannel = {binding = "love.thread.getChannel", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"name"}, ["fnl/docstring"] = "Creates or retrieves a named thread channel.\n\nReturns -\n * channel (`Channel`) - The Channel object associated with the name."}}, newChannel = {binding = "love.thread.newChannel", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Create a new unnamed thread channel.\n\nOne use for them is to pass new unnamed channels to other threads via Channel:push on a named channel.\n\nReturns -\n * channel (`Channel`) - The new Channel object."}}, newThread = {binding = "love.thread.newThread", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new Thread from a filename, string or FileData object containing Lua code.\n\nReturns -\n * thread (`Thread`) - A new Thread that has yet to be started."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Allows you to work with threads.\n\nThreads are separate Lua environments, running in parallel to the main code. As their code runs separately, they can be used to compute complex operations without adversely affecting the frame rate of the main thread. However, as they are separate environments, they cannot access the variables and functions of the main thread, and communication between threads is limited.\n\nAll LOVE objects (userdata) are shared among threads so you'll only have to send their references across threads. You may run into concurrency issues if you manipulate an object on multiple threads at the same time.\n\nWhen a Thread is started, it only loads the love.thread module. Every other module has to be loaded with require."}}, threaderror = {binding = "love.threaderror", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"thread", "errorstr"}, ["fnl/docstring"] = "Callback function triggered when a Thread encounters an error."}}, timer = {binding = "love.timer", fields = {getAverageDelta = {binding = "love.timer.getAverageDelta", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the average delta time (seconds per frame) over the last second.\n\nReturns -\n * delta (`number`) - The average delta time over the last second."}}, getDelta = {binding = "love.timer.getDelta", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the time between the last two frames.\n\nReturns -\n * dt (`number`) - The time passed (in seconds)."}}, getFPS = {binding = "love.timer.getFPS", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the current frames per second.\n\nReturns -\n * fps (`number`) - The current FPS."}}, getTime = {binding = "love.timer.getTime", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Returns the value of a timer with an unspecified starting time.\n\nThis function should only be used to calculate differences between points in time, as the starting time of the timer is unknown.\n\nReturns -\n * time (`number`) - The time in seconds. Given as a decimal, accurate to the microsecond."}}, sleep = {binding = "love.timer.sleep", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"s"}, ["fnl/docstring"] = "Pauses the current thread for the specified amount of time."}}, step = {binding = "love.timer.step", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Measures the time between two frames.\n\nCalling this changes the return value of love.timer.getDelta.\n\nReturns -\n * dt (`number`) - The time passed (in seconds)."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to the user's clock."}}, touch = {binding = "love.touch", fields = {getPosition = {binding = "love.touch.getPosition", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"id"}, ["fnl/docstring"] = "Gets the current position of the specified touch-press, in pixels.\n\nReturns -\n * x (`number`) - The position along the x-axis of the touch-press inside the window, in pixels.\n * y (`number`) - The position along the y-axis of the touch-press inside the window, in pixels."}}, getPressure = {binding = "love.touch.getPressure", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"id"}, ["fnl/docstring"] = "Gets the current pressure of the specified touch-press.\n\nReturns -\n * pressure (`number`) - The pressure of the touch-press. Most touch screens aren't pressure sensitive, in which case the pressure will be 1."}}, getTouches = {binding = "love.touch.getTouches", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets a list of all active touch-presses.\n\nReturns -\n * touches (`table`) - A list of active touch-press id values, which can be used with love.touch.getPosition."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface to touch-screen presses."}}, touchmoved = {binding = "love.touchmoved", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"id", "x", "y", "dx", "dy", "pressure"}, ["fnl/docstring"] = "Callback function triggered when a touch press moves inside the touch screen."}}, touchpressed = {binding = "love.touchpressed", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"id", "x", "y", "dx", "dy", "pressure"}, ["fnl/docstring"] = "Callback function triggered when the touch screen is touched."}}, touchreleased = {binding = "love.touchreleased", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"id", "x", "y", "dx", "dy", "pressure"}, ["fnl/docstring"] = "Callback function triggered when the touch screen stops being touched."}}, update = {binding = "love.update", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"dt"}, ["fnl/docstring"] = "Callback function used to update the state of the game every frame."}}, video = {binding = "love.video", fields = {newVideoStream = {binding = "love.video.newVideoStream", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"filename"}, ["fnl/docstring"] = "Creates a new VideoStream. Currently only Ogg Theora video files are supported. VideoStreams can't draw videos, see love.graphics.newVideo for that.\n\nReturns -\n * videostream (`VideoStream`) - A new VideoStream."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "This module is responsible for decoding, controlling, and streaming video files.\n\nIt can't draw the videos, see love.graphics.newVideo and Video objects for that."}}, visible = {binding = "love.visible", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"visible"}, ["fnl/docstring"] = "Callback function triggered when window is minimized/hidden or unminimized by the user."}}, wheelmoved = {binding = "love.wheelmoved", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y"}, ["fnl/docstring"] = "Callback function triggered when the mouse wheel is moved."}}, window = {binding = "love.window", fields = {close = {binding = "love.window.close", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Closes the window. It can be reopened with love.window.setMode."}}, fromPixels = {binding = "love.window.fromPixels", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"pixelvalue"}, ["fnl/docstring"] = "Converts a number from pixels to density-independent units.\n\nThe pixel density inside the window might be greater (or smaller) than the 'size' of the window. For example on a retina screen in Mac OS X with the highdpi window flag enabled, the window may take up the same physical size as an 800x600 window, but the area inside the window uses 1600x1200 pixels. love.window.fromPixels(1600) would return 800 in that case.\n\nThis function converts coordinates from pixels to the size users are expecting them to display at onscreen. love.window.toPixels does the opposite. The highdpi window flag must be enabled to use the full pixel density of a Retina screen on Mac OS X and iOS. The flag currently does nothing on Windows and Linux, and on Android it is effectively always enabled.\n\nMost L\195\150VE functions return values and expect arguments in terms of pixels rather than density-independent units.\n\nReturns -\n * value (`number`) - The converted number, in density-independent units."}}, getDPIScale = {binding = "love.window.getDPIScale", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the DPI scale factor associated with the window.\n\nThe pixel density inside the window might be greater (or smaller) than the 'size' of the window. For example on a retina screen in Mac OS X with the highdpi window flag enabled, the window may take up the same physical size as an 800x600 window, but the area inside the window uses 1600x1200 pixels. love.window.getDPIScale() would return 2.0 in that case.\n\nThe love.window.fromPixels and love.window.toPixels functions can also be used to convert between units.\n\nThe highdpi window flag must be enabled to use the full pixel density of a Retina screen on Mac OS X and iOS. The flag currently does nothing on Windows and Linux, and on Android it is effectively always enabled.\n\nReturns -\n * scale (`number`) - The pixel scale factor associated with the window."}}, getDesktopDimensions = {binding = "love.window.getDesktopDimensions", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?displayindex"}, ["fnl/docstring"] = "Gets the width and height of the desktop.\n\nReturns -\n * width (`number`) - The width of the desktop.\n * height (`number`) - The height of the desktop."}}, getDisplayCount = {binding = "love.window.getDisplayCount", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the number of connected monitors.\n\nReturns -\n * count (`number`) - The number of currently connected displays."}}, getDisplayName = {binding = "love.window.getDisplayName", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?displayindex"}, ["fnl/docstring"] = "Gets the name of a display.\n\nReturns -\n * name (`string`) - The name of the specified display."}}, getDisplayOrientation = {binding = "love.window.getDisplayOrientation", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?displayindex"}, ["fnl/docstring"] = "Gets current device display orientation.\n\nReturns -\n * orientation (`DisplayOrientation`) - Current device display orientation."}}, getFullscreen = {binding = "love.window.getFullscreen", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether the window is fullscreen.\n\nReturns -\n * fullscreen (`boolean`) - True if the window is fullscreen, false otherwise.\n * fstype (`FullscreenType`) - The type of fullscreen mode used."}}, getFullscreenModes = {binding = "love.window.getFullscreenModes", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?displayindex"}, ["fnl/docstring"] = "Gets a list of supported fullscreen modes.\n\nReturns -\n * modes (`table`) - A table of width/height pairs. (Note that this may not be in order.)"}}, getIcon = {binding = "love.window.getIcon", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the window icon.\n\nReturns -\n * imagedata (`ImageData`) - The window icon imagedata, or nil if no icon has been set with love.window.setIcon."}}, getMode = {binding = "love.window.getMode", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the display mode and properties of the window.\n\nReturns -\n * width (`number`) - Window width.\n * height (`number`) - Window height.\n * flags (`table`) - Table with the window properties:"}}, getPosition = {binding = "love.window.getPosition", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the position of the window on the screen.\n\nThe window position is in the coordinate space of the display it is currently in.\n\nReturns -\n * x (`number`) - The x-coordinate of the window's position.\n * y (`number`) - The y-coordinate of the window's position.\n * displayindex (`number`) - The index of the display that the window is in."}}, getSafeArea = {binding = "love.window.getSafeArea", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets area inside the window which is known to be unobstructed by a system title bar, the iPhone X notch, etc. Useful for making sure UI elements can be seen by the user.\n\nReturns -\n * x (`number`) - Starting position of safe area (x-axis).\n * y (`number`) - Starting position of safe area (y-axis).\n * w (`number`) - Width of safe area.\n * h (`number`) - Height of safe area."}}, getTitle = {binding = "love.window.getTitle", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets the window title.\n\nReturns -\n * title (`string`) - The current window title."}}, getVSync = {binding = "love.window.getVSync", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets current vertical synchronization (vsync).\n\nReturns -\n * vsync (`number`) - Current vsync status. 1 if enabled, 0 if disabled, and -1 for adaptive vsync."}}, hasFocus = {binding = "love.window.hasFocus", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the game window has keyboard focus.\n\nReturns -\n * focus (`boolean`) - True if the window has the focus or false if not."}}, hasMouseFocus = {binding = "love.window.hasMouseFocus", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the game window has mouse focus.\n\nReturns -\n * focus (`boolean`) - True if the window has mouse focus or false if not."}}, isDisplaySleepEnabled = {binding = "love.window.isDisplaySleepEnabled", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether the display is allowed to sleep while the program is running.\n\nDisplay sleep is disabled by default. Some types of input (e.g. joystick button presses) might not prevent the display from sleeping, if display sleep is allowed.\n\nReturns -\n * enabled (`boolean`) - True if system display sleep is enabled / allowed, false otherwise."}}, isMaximized = {binding = "love.window.isMaximized", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether the Window is currently maximized.\n\nThe window can be maximized if it is not fullscreen and is resizable, and either the user has pressed the window's Maximize button or love.window.maximize has been called.\n\nReturns -\n * maximized (`boolean`) - True if the window is currently maximized in windowed mode, false otherwise."}}, isMinimized = {binding = "love.window.isMinimized", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Gets whether the Window is currently minimized.\n\nReturns -\n * minimized (`boolean`) - True if the window is currently minimized, false otherwise."}}, isOpen = {binding = "love.window.isOpen", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the window is open.\n\nReturns -\n * open (`boolean`) - True if the window is open, false otherwise."}}, isVisible = {binding = "love.window.isVisible", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Checks if the game window is visible.\n\nThe window is considered visible if it's not minimized and the program isn't hidden.\n\nReturns -\n * visible (`boolean`) - True if the window is visible or false if not."}}, maximize = {binding = "love.window.maximize", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Makes the window as large as possible.\n\nThis function has no effect if the window isn't resizable, since it essentially programmatically presses the window's 'maximize' button."}}, minimize = {binding = "love.window.minimize", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Minimizes the window to the system's task bar / dock."}}, requestAttention = {binding = "love.window.requestAttention", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"?continuous"}, ["fnl/docstring"] = "Causes the window to request the attention of the user if it is not in the foreground.\n\nIn Windows the taskbar icon will flash, and in OS X the dock icon will bounce."}}, restore = {binding = "love.window.restore", metadata = {["fls/itemKind"] = "Function", ["fnl/docstring"] = "Restores the size and position of the window if it was minimized or maximized."}}, setDisplaySleepEnabled = {binding = "love.window.setDisplaySleepEnabled", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"enable"}, ["fnl/docstring"] = "Sets whether the display is allowed to sleep while the program is running.\n\nDisplay sleep is disabled by default. Some types of input (e.g. joystick button presses) might not prevent the display from sleeping, if display sleep is allowed."}}, setFullscreen = {binding = "love.window.setFullscreen", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"fullscreen"}, ["fnl/docstring"] = "Enters or exits fullscreen. The display to use when entering fullscreen is chosen based on which display the window is currently in, if multiple monitors are connected.\n\nReturns -\n * success (`boolean`) - True if an attempt to enter fullscreen was successful, false otherwise."}}, setIcon = {binding = "love.window.setIcon", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"imagedata"}, ["fnl/docstring"] = "Sets the window icon until the game is quit. Not all operating systems support very large icon images.\n\nReturns -\n * success (`boolean`) - Whether the icon has been set successfully."}}, setMode = {binding = "love.window.setMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"width", "height", "flags"}, ["fnl/docstring"] = "Sets the display mode and properties of the window.\n\nIf width or height is 0, setMode will use the width and height of the desktop. \n\nChanging the display mode may have side effects: for example, canvases will be cleared and values sent to shaders with canvases beforehand or re-draw to them afterward if you need to.\n\nReturns -\n * success (`boolean`) - True if successful, false otherwise."}}, setPosition = {binding = "love.window.setPosition", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"x", "y", "?displayindex"}, ["fnl/docstring"] = "Sets the position of the window on the screen.\n\nThe window position is in the coordinate space of the specified display."}}, setTitle = {binding = "love.window.setTitle", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"title"}, ["fnl/docstring"] = "Sets the window title."}}, setVSync = {binding = "love.window.setVSync", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"vsync"}, ["fnl/docstring"] = "Sets vertical synchronization mode."}}, showMessageBox = {binding = "love.window.showMessageBox", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"title", "message", "?type", "?attachtowindow"}, ["fnl/docstring"] = "Displays a message box dialog above the love window. The message box contains a title, optional text, and buttons.\n\nReturns -\n * success (`boolean`) - Whether the message box was successfully displayed."}}, toPixels = {binding = "love.window.toPixels", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"value"}, ["fnl/docstring"] = "Converts a number from density-independent units to pixels.\n\nThe pixel density inside the window might be greater (or smaller) than the 'size' of the window. For example on a retina screen in Mac OS X with the highdpi window flag enabled, the window may take up the same physical size as an 800x600 window, but the area inside the window uses 1600x1200 pixels. love.window.toPixels(800) would return 1600 in that case.\n\nThis is used to convert coordinates from the size users are expecting them to display at onscreen to pixels. love.window.fromPixels does the opposite. The highdpi window flag must be enabled to use the full pixel density of a Retina screen on Mac OS X and iOS. The flag currently does nothing on Windows and Linux, and on Android it is effectively always enabled.\n\nMost L\195\150VE functions return values and expect arguments in terms of pixels rather than density-independent units.\n\nReturns -\n * pixelvalue (`number`) - The converted number, in pixels."}}, updateMode = {binding = "love.window.updateMode", metadata = {["fls/itemKind"] = "Function", ["fnl/arglist"] = {"width", "height", "settings"}, ["fnl/docstring"] = "Sets the display mode and properties of the window, without modifying unspecified properties.\n\nIf width or height is 0, updateMode will use the width and height of the desktop. \n\nChanging the display mode may have side effects: for example, canvases will be cleared. Make sure to save the contents of canvases beforehand or re-draw to them afterward if you need to.\n\nReturns -\n * success (`boolean`) - True if successful, false otherwise."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "Provides an interface for modifying and retrieving information about the program's window."}}}, metadata = {["fls/itemKind"] = "Module", ["fnl/docstring"] = "L\195\150VE is a framework for making 2D games in the Lua programming language."}}}
